style.css:
body, html {
    background-image: linear-gradient(rgba(0, 0, 0, 0.5), rgba(0, 0, 0, 0.5)), url("https://img.freepik.com/free-photo/beautiful-anime-character-cartoon-scene_23-2151035176.jpg?t=st=1738320027~exp=1738323627~hmac=4f7657d51b73d4ca317d5c78137cc1172390e29c59e58621e85f0da019dcf16a&w=1800");
    background-size: cover; /* Ensures the image covers the entire background */
    background-position: center; /* Centers the image */
    background-repeat: no-repeat; /* Prevents the image from repeating */
    height: 100%; /* Ensures the body and html take up the full height of the viewport */
    margin: 0; /* Removes default margin */
    padding: 0; /* Removes default padding */
}
